    private function failTrigger(string $kind):void{$table=match($kind){'case'=>'arpa_appointment_historical_approval_case','amendment-event'=>'arpa_appointment_correction_amendment_event',default=>'arpa_appointment_historical_approval_event'};$this->pdo->exec("CREATE TRIGGER auto_registration_failure BEFORE INSERT ON {$table} FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic mandatory registration failure'");}
    private function dropFailure():void{$this->pdo->exec('DROP TRIGGER auto_registration_failure');}
