    public static function worker(array $args):void{$test=new self();$test->pdo=self::connect($args[2]);(new ReflectionProperty(Database::class,'pdo'))->setValue(null,$test->pdo);$test->sourceFixture=new ArpaHistoricalAppointmentApprovalIsolatedTest();(new ReflectionProperty($test->sourceFixture,'pdo'))->setValue($test->sourceFixture,$test->pdo);$test->context($args[3]==='bulk'?3:($args[3]==='amendment'?9:1));try{if($args[3]==='direct')$test->correct(['request'=>$args[4],'appointment'=>$args[5]]);elseif($args[3]==='bulk')(new ArpaAppointmentDataIssueCorrectionService($test->pdo))->promoteCanonicalAppointmentFromBulk($args[5],self::ADMIN,'synthetic-concurrent-batch');else(new ArpaAppointmentCorrectionAmendmentService($test->pdo))->review($args[6],'APPROVE',6,self::actor(9));echo 'OK';}catch(DomainException){echo 'BLOCKED';}}
    private static function connect(string $db):PDO{if(!preg_match('/^dems_test_hist_auto_[a-f0-9]{10}$/D',$db))throw new RuntimeException('Unsafe isolated database name.');$c=config('database');return new PDO(sprintf('mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',$c['host'],$c['port'],$db),$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false,PDO::MYSQL_ATTR_MULTI_STATEMENTS=>true]);}
    private static function actor(int $n):string{return '00000000-0000-4000-8000-'.str_pad((string)$n,12,'0',STR_PAD_LEFT);}
    private function state():array{$out=[];foreach($this->pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $t)$out[$t]=$this->pdo->query('SELECT * FROM `'.$t.'` ORDER BY 1')->fetchAll();return $out;}
    private function row(string $table,string $id):array{return $this->one('SELECT * FROM '.$table.' WHERE id=?',[$id]);}
    private function one(string $sql,array $params):array{$s=$this->pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();if(count($rows)!==1)throw new RuntimeException('Expected one isolated fixture row.');return $rows[0];}
    private function count(string $table,string $field,string $id):int{$s=$this->pdo->prepare('SELECT COUNT(*) FROM '.$table.' WHERE '.$field.'=?');$s->execute([$id]);return (int)$s->fetchColumn();}
    private function call(object $o,string $m,mixed ...$args):mixed{return(new ReflectionMethod($o,$m))->invoke($o,...$args);}
    private function same(mixed $e,mixed $a,string $m):void{$this->assertions++;if($e!==$a)throw new RuntimeException($m.'; expected '.var_export($e,true).', got '.var_export($a,true));}
    private function fails(callable $work,string $message,bool $insertionFailure=false):void{$this->assertions++;try{$work();}catch(Throwable $e){if($insertionFailure){if(!$e instanceof PDOException||!str_contains($e->getMessage(),'Synthetic mandatory registration failure'))throw $e;}elseif(!$e instanceof DomainException)throw $e;return;}throw new RuntimeException($message.'; expected failure.');}
    private function denied(callable $work,string $message):void{$this->assertions++;try{$work();}catch(DomainException $e){if($e->getCode()!==403)throw new RuntimeException($message.'; expected 403, got '.$e->getCode());return;}throw new RuntimeException($message.'; expected authorization denial.');}
